globalThis.ANDE_CHUNKS["0260d5b9c05f038ecbdc8083170e47f9333422191691af32302c63d6abad2638"] = [{"id":"quark_social:100000880021","sourceKey":"quark_social","company":"夸克","title":"千问事业部-千问/夸克-Post-Training 高级算法专家-北京/杭州","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100000880021&track_id=SSP1791223760285DkFCQTuxLZ1715","duty":"岗位描述：\n全面负责千问大模型在 Post-Training 能力进化和上限突破、持续推进模型能力边界和商业价值的不断延伸。通过对前沿算法的极致探索和高效能工程体系的构建，驱动模型在逻辑推理、问答、复杂多轮上下文、指令遵循、Agent 智能体、多模态交互等关键领域实现突破性进展，打造世界一流的模型效果，并定义其在未来 AI 应用中的核心价值。\n\n工作职责：\n● 【战略规划与技术引领】 制定并执行大模型 Post-training 的中长期技术路线图，预判并布局下一代对齐技术、能力增强及对齐方案。主导核心算法的战略方向，确保技术路径与公司业务战略高度协同。\n● 【核心能力与壁垒构建】 领导团队进行体系化的数据驱动实验，不仅局限于日常迭代，更要建立可规模化的能力提升范式。您将攻坚并解决模型在复杂指令遵循、通用问答、RAG、深度逻辑推理、内容创作、Tool-Using 等方面的瓶颈问题，构建技术","requirements":"● 计算机科学、人工智能、电子工程或相关领域的硕士或博士学位。\n● 在顶级学术会议 (NeurIPS, ICML, ICLR, ACL, EMNLP 等) 发表过相关高质量论文。\n● 在自然语言处理 (NLP) 或大模型 (LLM/VLM) 领域拥有 3 年以上的研发经验，对 Post-training 技术（SFT, RLHF, DPO, PPO、RLVR 等）方向拥有深厚的理论功底和业界公认的成功实践案例。\n● 对深度学习和机器学习有精深的理解，尤其熟悉 Transformer、MoE 等前沿模型架构。在强化学习 (RL) 领域有扎实的理论基础，并主导过其在 LLM 中的创新应用。\n● 具备卓越的工程实现能力，精通 Python 及主流深度学习框架 (PyTorch/TensorFlow)。\n● 具备出色的算法设计与分析能力，能够独立设计、执行和分析复杂的模型实验。\n● 具备优秀的领导","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100000920011","sourceKey":"quark_social","company":"夸克","title":"千问事业部-千问/夸克-大模型高级算法专家-Chat方向","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100000920011&track_id=SSP1791223760627oJYBvCIxjF2703","duty":"全面负责定义、设计并实现下一代对话系统的核心算法与交互范式，解决当前对话模型在多轮交互、知识应用、共情能力等方面的挑战，探索并引领模型在个性化、主动性、拟人化等前沿方向的技术突破。直接决定数亿夸克用户在Chat场景的与AI 的交互体验，塑造夸克在未来对话式 AI 时代的领先地位。\n\n1. 对话体验定义与规划。深入分析用户意图与行为，结合业务场景，制定并执行对话体验的中长期技术演进路线图。并密切追踪并研究对话式 AI 领域的最新进展，包括主动式对话策略、多模态对话 (语音/视觉融合)、AI Agent 中的对话流控制等。您将主导定义“顶级对话体验”的标准，并将其分解为可落地、可量化的算法迭代目标。\n2. 多轮对话与上下文理解。攻坚并解决长程、复杂多轮对话中的核心技术难题，包括但不限于指令遵循、上下文精准理解、长程记忆与遗忘机制、隐式意图识别等。您将设计创新的模型结构与训练策略，使模型具备真正","requirements":"1. 拥有计算机科学、人工智能或相关领域的博士学位者优先，硕士学位亦可。\n2. 至少 3 年在自然语言处理 (NLP) 或大语言模型 (LLM) 领域的研发经验，对对话系统、对话式 AI 有深刻的理解和丰富的实战经验。在学术界或工业界有公认的对话技术相关成果。\n3. 在以下一个或多个领域拥有一流的技术水准和成功经验：多轮对话管理、大模型的对齐技术（如 SFT/RLHF/RLAIF/DPO、知识增强生成、个性化生成）在对话场景的深度应用。\n4. 对深度学习和机器学习有精深的理解，尤其熟悉 Transformer、MoE 等前沿模型架构，精通 Python 及主流深度学习框架 (PyTorch/TensorFlow)。在大模型 Post-training 领域有扎实的理论基础，并主导过其在 LLM 中的创新应用。\n5. 具备以下条件者将获得优先考虑：\n--主导或核心参与过业界知名的对话系统或聊","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100000980012","sourceKey":"quark_social","company":"夸克","title":"千问事业部-高级客户端开发工程师-AI协作工具","city":"杭州/广州","category":"技术类-开发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100000980012&track_id=SSP1791223753116XPYUnXTihX9599","duty":"1、负责AI工作台产品、AI浏览器等AI协作产品PC平台核心产品功能的全链路研发与迭代，保障桌面客户端（Windows/Mac）的功能一致性与极致用户体验；\n2、负责AI协作产品的AI Agent在各种场景的业务落地和开发工作，提供系统级、浏览器以及各种软件的互操作支持能力；\n3、参与设计大前端侧的 AI 基础设施，推进 MCP 的接入，打通底层数据逻辑与上层 AI 技能，构建稳定高效的端侧大模型调用与调度引擎；\n4、跟踪大前端及 AI 领域前沿技术（如端侧小模型部署、端侧智能体自动化流编排、WebGPU 等），结合AI协作工具产品跨平台核心产品业务场景进行技术原型调研与落地。","requirements":"1、具备Windows、Mac、Linux至少一个平台的PC客户端的开发经验，熟悉C++，OC，Swift开发语言，有大型协作办公软件或者AI工具类产品经验者优先；\n2、熟悉 Chromium / Electron / CEF 开发模式及相关工具链的使用，有相关开发经验者优先；\n3、具备AI Agent的实际开发经验，熟悉 LLM 工作原理与应用开发（如 Prompt Engineering、Function Calling/Tool Use、RAG 架构），了解或使用过相关 Agent 开发框架者优先；\n4、具备扎实的前端基础，精通 HTML / CSS / JavaScript 有前端开发经验者优先；\n5、对AICoding提效有实践经验，在工程落地中有自主开发SOP、SKILL等AICoding基建，提升开发迭代效率；\n6、自驱力强，具备良好的逻辑思维与跨团队沟通协作能力，能独立承担","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100000980032","sourceKey":"quark_social","company":"夸克","title":"千问事业部-高级AI客户端研发（智能创作）工程师-广州","city":"广州","category":"技术类-开发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100000980032&track_id=SSP1791223757205PIFjBapzdU4962","duty":"1. 负责千问App的智能创作业务（AI生图、AI视频、AI修图）的功能开发，架构设计以及体验优化；\n2. 负责AI Native应用的全新交互和体验，将前沿的AIGC技术转化为用户可感知的功能；\n3. 与产品团队紧密合作，持续关注行业动态和用户反馈，通过技术手段升级Agent能力，为用户创造全新AI Native体验。","requirements":"1. 本科以上，具有良好的数据结构和架构设计能力，掌握常见设计模式，有阅读源码习惯；\n2. 至少精通一个平台（安卓/iOS）的客户端开发，了解平台的Framework 原理和底层机制，有C++、KMP/CMP等跨端经验优先；\n3. 具备良好的业务理解能力，能主动提出想法，通过技术手段促进业务目标达成；\n4. 具备良好的分析问题能力，有性能优化和技术攻关经验，有数据驱动意识，有技术热情；\n5. 有AI Native应用开发经验者优先，有深度AI Coding实践或者基建者优先；","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100001760004","sourceKey":"quark_social","company":"夸克","title":"千问事业部-多模态大模型Posttrain算法专家-北京/广州","city":"北京/广州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100001760004&track_id=SSP1791223759948dQYhksglxW2520","duty":"千问多模态推理算法致力于使用AI在Agentic、stem等方向的效果提升。在这里您将与我们一起挑战前沿的产品技术问题，并收获服务千万级用户的成就感和影响力。\n1. 负责面向推理的多模态大模型研发，包括图文、视频、音频等多个模态的预训练，探索多模态的数据质量评估和清洗方法；\n2. 负责对模型的训练数据、训练策略、模型结构等进行深入分析。\n3. 负责强化学习算法研发、提升训练稳定性、采样效率、训练效果。\n4. 负责跟踪和研究多模态大模型前沿技术调研、落地、对业务进行优化；\n5. 负责对各业务场景下相关技术问题进行分析、算法设计、研发以及推动上线，提升业务效果；","requirements":"1. 计算机相关专业硕士及以上学历；具有较强的逻辑分析能力，对数据敏感；\n2. 熟悉 Linux 和 Python，熟悉Pytorch, transformers 等工具使用，了解分布式训练框架如Deepspeed、Megatron-LM等，熟悉大规模分布式训练，具备优秀的工程开发能力；\n3. 精通业界主流的Posttrain技术、包括不限于Grpo、Gspo等，在Agentic RL、stem、general Reasoning等方向有实践经验优先。\n4. 在国际顶尖会议或期刊（包括但不限于CVPR, ICCV, ECCV, NeurIPS, ICML, ICLR等）上发表过论文者优先；\n5. 较强的业务问题到算法模型的建模能力，有强烈的求知欲、自驱力和进取心，能及时关注和学习业界最佳实践， 乐于面对挑战， 负责敬业，优秀的团队合作精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100003740002","sourceKey":"quark_social","company":"夸克","title":"千问事业部-高级前端开发工程师-AI协作工具产品","city":"杭州/广州","category":"技术类-前端","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100003740002&track_id=SSP1791223753116zcuBdQwutn5201","duty":"1.负责千问产品功能的全链路研发与迭代，保障 Web 端、桌面客户端（Windows/Mac）及移动端（iOS/Android）的极致用户体验；\n2.负责千问核心产品场景的 AI Agent 开发与工程化落地；\n3.参与设计端侧的 AI 基础设施，打通底层数据逻辑与上层 AI 工具、技能、连接器，构建稳定高效的端侧大模型调用与调度引擎；\n4.负责千问多端产品的性能优化，攻克对话列表渲染、AI 推理过程中的交互卡顿、大文件及复杂上下文本地缓存同步等难题；\n5.深入操作系统底层，解决文件同步、离线存储、多端状态同步以及跨端通信等核心场景下的兼容性与技术难题。","requirements":"1.本科及以上学历，计算机或软件工程相关专业。3-5年互联网研发经验，有网盘、云存储、大型协作办公产品或 AI 工具类产品经验者优先；\n2.具备 AI Agent 的实际开发落地经验。熟悉 LLM 工作原理与应用开发（如 Prompt Engineering、Function Calling/Tool Use、RAG 架构），了解或使用过相关 Agent 开发框架（如 LangChain、AutoGPT、Semantic Kernel 等）及本地调度编排引擎；\n3.扎实的桌面端（Windows/Mac）、移动端（iOS/Android）、前端技术基础，具备优秀的工程化与前端架构能力；\n4.具备 Web端，桌面端（Windows/Mac）或移动端（iOS/Android）至少一到两个平台的实际开发经验；\n5.有 Chromium 架构、Electron、CEF 或 CMP 等跨平台框架的实际","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100004260002","sourceKey":"quark_social","company":"夸克","title":"千问事业部-高级AI业务运维工程师-广州/杭州","city":"广州","category":"技术类-运维","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100004260002&track_id=SSP1791223754835VicBGyAAae9187","duty":"1、负责AI业务应用技术运维，包括不限于规划、评审、搭建、架构优化与稳定性工作，挑战海量用户架构；\n2、制定运维工作标准及演进方案，主导并推进方案实施和落地，不断提升稳定性水位及SRE体系优化；\n3、根据日常运维工作，参与设计运维平台和自动化能力需求，推进需求实现和落地；\n4、以技术和管理手段相结合，识别业务及基础设施问题和风险，协同定位，组织推进、解决业务问题和风险；\n5、关键业务和业务重要活动的稳定性保障，包括整体的运维架构、部署监控方案的设计和实施。","requirements":"1、大学本科及以上学历，计算机或者相关专业，3年以上相关工作经验；\n2、精通linux操作系统及常见的TCP/HTTP等协议原理，对稳定性及系统性能相关问题有较深刻理解；\n3、熟悉负载均衡及常见Web服务器、应用服务器、数据库服务器的监控、故障解决和性能调优；\n4、熟悉阿里云ECS、OSS、SLB、CDN等云产品，并了解云计算平台OpenStack、Kubernetes及docker/kvm/xen等虚拟化技术和原理；\n5、热爱技术，自我驱动，主动思考，不断钻研和探索新领域，有较好的技术敏感度、风险识别能力和全局意识；\n6、高度的责任心，良好的客户服务意识及良好的沟通和协调能力，积极主动，以结果和行动为准则；\n7、有互联网大规模应用系统的运维和优化经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100004320002","sourceKey":"quark_social","company":"夸克","title":"千问事业部-MOS 实验室-推荐/推送算法专家（大模型方向）-杭州/北京/广州","city":"北京/杭州/广州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100004320002&track_id=SSP1791223756210FRrzbEHlWf7964","duty":"关于我们：\nMOS 实验室隶属于阿里 ATH 千问事业群。我们致力于在大模型时代打造具有全球影响力的 AI 原生产品，推动 AI 从“被动对话”向“主动服务与复杂执行”的范式跃迁。\n实验室核心业务涵盖 AI 搜索、生成式推荐、主动服务及任务助理 Agent 等前沿领域。依托千问大模型底座，我们深度探索 RAG、Agentic RL、多 Agent 协作及全链路工程自动化技术，旨在构建能够深度理解用户、自主规划路径并闭环交付任务的“最强 AI 助手”。\n岗位职责：定义大模型时代的主动推荐\n1. 主动服务场景构建： 负责千问场景下的主动推荐算法研发。基于用户长期记忆与画像，构建主动发起聊天话题、引导任务执行的算法体系。\n2. 生成式推荐探索： 探索 LLM-Native 的推荐范式，利用大模型的原生推理能力实现生成式推荐（Generative Recommendation），打破传统过滤式推荐","requirements":"1. 推荐领域资深背景： 拥有丰富的荐系统或推送业务经验，对召回、排序、重排等经典架构有深刻理解。\n2. 大模型实战经验： 熟悉主流大模型的应用逻辑，有生成式推荐、Agent 推理或 LLM-based 策略优化实战经验者优先。\n3. 策略与建模能力：\n    ○ 精通传统推荐算法（如多任务学习、强化学习、序列建模）。\n    ○ 在推送算法、用户生命周期建模、或 Uplift Model 等增量建模方向有成功案例。\n4. 敏锐的业务洞察： 能够从用户体验角度出发设计算法，对“主动服务”场景有独特的思考，不拘泥于单纯的技术实现。\n5. 工程与硬技能： 极其扎实的编程功底（Python/Java/C++），熟悉主流深度学习框架，具备处理海量数据、实现复杂逻辑落地的能力。\n加分项\n● 在推荐系统或 NLP 顶会（RecSys, SIGIR, KDD, ACL 等）发表过大模型推荐相关论文。\n●","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100004360008","sourceKey":"quark_social","company":"夸克","title":"千问事业部-传感器系统软件专家-杭州/上海/深圳","city":"深圳/杭州/上海","category":"技术类-开发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100004360008&track_id=SSP1791223757541BrBedeDwQA9321","duty":"1、负责Android/linux/RTOS平台传感器的驱动、HAL、Framework层软件开发 ；\n2、负责设计、研发或集成与传感器相关的算法和新功能；\n3、负责传感器相关软硬件调试，厂测校准，可靠性和性能优化。","requirements":"1、本科以上学历，计算机、通信、电子信息等相关专业，5年以上嵌入式底层系统软件开发经验；\n2、精通常见的IMU、地磁、A+G IMU、压感，电容类sensor，ALS、Psensor等典型sensor\n3、精通相关sensor物理特性，校准原理和方法，厂测手段，可靠性设计和性能功耗优化\n4、有耳机、眼镜、手表等可穿戴产品上sensor相关经验的优先；\n5、熟悉高通SEE、MTK SCP等主控sensor框架和集成，有传感器融合应用经验者优先;\n6、有常见(i2c/ spi/ usb/ lcd/ touch/charger/IR等)的其他外设驱动开发经验的优先；\n7、有Linux、RTOS、Android系统底软广泛经验的加分；\n8、具备较强的学习和问题分析能力，工作积极主动，团队协作意识强。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100004660003","sourceKey":"quark_social","company":"夸克","title":"千问事业部-视觉数据和系统研发专家-杭州","city":"杭州","category":"技术类-开发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100004660003&track_id=SSP1791223759289ftiUoyeKCt7258","duty":"1. 负责夸克业务的离线流程开发与迭代，构建高效稳定的端到端数据处理流水线；\n2. 深入优化数据采集、清洗、标注、报表等核心流程，提升整体处理效率；\n3. 引入业界新技术，推动流程架构升级，实现业务性能、系统稳定性和成本效益的持续提升。","requirements":"1. 熟练掌握至少一种编程语言：Python / C++ / Java，具有扎实的基础算法和数据结构知识；\n2. 有丰富的Linux后台开发经验，熟练掌握服务端架构设计、开发和调试技能；\n3. 熟悉Hadoop/Spark/Flink等大数据处理框架，有流程自动化改造经验优先；\n4. 具备良好的产品和业务sense，有大模型应用的深度使用、开发落地经验优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100005600003","sourceKey":"quark_social","company":"夸克","title":"千问事业部-技术专家-电源/充电","city":"上海","category":"技术类-开发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100005600003&track_id=SSP1791223759289DuGVYmKApN6912","duty":"1. 负责整体电源架构设计，包括电源树（Power Tree）、电源分配网络（PDN）。主导关键电源器件（如PMIC、Charger IC、LDO、DC-DC）的选型和评估。\n2. 建立和完善整机及各场景（待机、音频、显示等）的功耗分析模型。与硬件、软件、算法团队协同，制定并实施系统级的功耗优化方案。\n3. 负责充电方案设计与调试，确保其高效、安全、可靠。深入理解并主导实现多种充电协议（如USB PD、QC、VOOC、Wireless Charging等）。解决充电过程中的热管理、电池健康度等关键技术难题。\n4. 与软件合作，优化电池电量计算法，提升电量估算精度。制定电池安全策略和寿命管理策略。\n5. 跟踪业界新的电源管理技术和趋势，进行前瞻性技术研究和原型开发。为下一代产品规划提供电源技术方面的决策支持。\n6. 主导解决产品开发、测试及客户反馈中出现的各类复杂电源相关问题。","requirements":"1. 电子工程、微电子、通信工程等相关专业，本科及以上学历。5年以上手机或消费电子类产品电源开发相关工作经验，有主导或深度参与量产项目电源设计的成功经验。\n2.精通模拟电路，深刻理解电源管理集成电路（PMIC, Charger, LDO, Buck/Boost Converter）的工作原理和特性。精通电源完整性（PI） 和信号完整性（SI）的基本概念，具备丰富的PCB布局（Layout）设计指导经验。熟练掌握至少一种原理图和PCB设计工具（如Cadence Allegro, PADS）进行电路分析和审查。熟练掌握各种实验室测试仪器，如示波器、电源、电子负载、功率分析仪等。对高通、联发科（MTK）等主流手机平台电源架构有深入理解者优先。在电池电量计算法、电池建模方面有实际项目经验者优先。\n3. 具备出色的问题分析和解决能力，能够应对复杂的技术挑战。优秀的沟通能力和团队协作精神，能够跨部门推","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100006360004","sourceKey":"quark_social","company":"夸克","title":"千问事业部-GTM业务拓展专家-杭州","city":"杭州","category":"市场拓展-BD","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100006360004&track_id=SSP1791223757880MSxUhaEauT5947","duty":"1. 产品操盘策略：深度参与产品打造，根据核心特点、目标市场定位，组织制定新品整体销售目标并分解至各渠道，制定新品上市和老品销售方案。\n2. 资源整合：拉通产品、Marketing、交付、服务等多条线资源输出打法和销售策略，营销资源匹配产品策略，聚焦重点市场，确保产品可持续热度。\n3. 产品激活&渠道库存管理：关注渠道库存维持在合理范围，协调并跟进各电商平台/客户达成销售激活目标，对产品生命周期内的经营指标负责。\n4. 产品复盘：针对每款产品的上市首发、大促营销、下市等进行深度复盘，总结各环节经验和不足，不断激发新的方案、新的思路。\n5. 产品市场分析：分析市场销量、竞争格局，发现差距和机会，制定或调整新老产品组合及策略；分析竞争对手打法、竞争推演，发现问题，预测风险。","requirements":"1. 本科及以上学历，8年及以上GTM工作经验优先。\n2. 沟通能力强，性格开朗，责任心强，为人诚信正直，胆大心细、有执行力。\n3. 熟悉国内3C市场特征，熟悉主力品类全渠道、竞争状态、用户特征等。\n4. 具备较强的数据分析处理能力、逻辑思维、系统性思维。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100006700017","sourceKey":"quark_social","company":"夸克","title":"千问事业部-健康算法评测专家-杭州","city":"杭州","category":"技术类-质量保证","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100006700017&track_id=SSP1791223754835wQIwVEmeZk2314","duty":"1、负责心率、HRV、血氧、血压估算、睡眠分期、运动伪影消除等健康算法的评测方案设计、基准数据集构建与评测工程实现，确保算法精度与鲁棒性满足产品需求。\n2、建设面向健康场景的大模型评估体系（Benchmark），设计生理数据 + 用户画像多模态输入的评测集，覆盖健康状态推理、趋势分析、个性化建议生成等任务；建立评测结果的智能化判定与人工校准机制，输出专业评测报告。\n3、针对 MCU/低功耗芯片上的模型量化（INT8）、剪枝与 DSP 优化，设计精度损失评估与性能（功耗/时延/内存）评测方案，验证端云一致性。\n4、主导健康功能从算法版本、固件到 App 的全链路测试，制定评测规范与准入准出标准，识别并推动风险收敛。\n5、追踪生理信号处理、多传感器融合与大模型评测领域的前沿进展，将新方法落地到评测工具链；协同算法、固件、产品、硬件等多角色团队，驱动问题闭环。","requirements":"1、本科及以上学历，3-5 年测试 / 算法评测工作经验，具备多模态算法、大模型、音视频或图像算法之一的评测背景；\n2、熟悉以下至少一类健康算法的原理与评测方法：PPG/ECG 信号处理、运动伪影去除、HRV/血氧/睡眠分期等指标计算，理解其生理学原理而非仅会调用；\n3、掌握大模型评测方法论，有构建 Benchmark、评测集或评测平台的实践经验，了解主流评测指标（准确率、一致性、幻觉率、安全性等）及其局限；\n4、熟悉 Python，具备自动化评测框架设计开发能力，能独立完成评测数据管道与分析工具建设；\n5、良好的跨团队沟通与项目推动能力，能主导大型项目的测试规划、进度管理与风险控制。\n\n加分项：\n1、有智能穿戴设备（眼镜/耳机/手环/手表）健康算法落地与评测经验，熟悉端侧资源约束下的模型部署验证。了解 TinyML、模型量化/剪枝、C/C++ 嵌入式开发或 DSP 优化，能读懂并评估边缘","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100006720002","sourceKey":"quark_social","company":"夸克","title":"千问事业部-产品营销专家-杭州","city":"杭州","category":"市场-产品市场营销","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100006720002&track_id=SSP1791223755185LRldVdIMHe3232","duty":"1.产品卖点与心智建设：负责产品营销卖点策略提炼，从用户需求和竞品对标出发，打造精准的产品定位及产品卖点策略，综合运用内容营销、媒体合作、活动策划等多种手段，系统性建设产品认知与用户心智；确保产品卖点从定义到营销的全流程一致性打法；\n2.产品用户场景拓展：在产品立项、规划阶段深度参与构建，挖掘高潜力目标人群及其使用场景，设计从认知到转化的完整路径，推动产品使用率与获客目标达成；\n3.创意传播活动策划：基于产品特性，策划具备社交传播力、用户参与度高的线上线下营销活动，实现破圈效应与用户自发传播；\n4.跨团队高效协同：紧密联动产品、用增、设计、运营等团队，快速推进营销项目从策略到落地的全过程，确保执行效率与效果。","requirements":"1.洞察与提炼能力：熟练掌握洞察方法并对产品、行业、竞品、消费者进行洞察，给产品线带来市场声音的输入，并能够快速理解复杂产品逻辑，并精准提炼差异化卖点与用户价值主张；\n2.规划能力：能输出结构化规划，具备产品周期意识，能根据产品所处阶段（冷启动/成长/成熟）制定匹配的营销策略；\n3.项目经验：有成功打造过具备行业影响力或广泛用户参与度的市场营销项目经验（请附案例）；\n4.沟通影响力：出色的跨部门沟通与项目管理能力，能在快节奏环境中高效推进多线程任务；\n5.加分项，有AI领域相关项目经验，具备高成长性市场方法，对内容和创意敏感。\n\n经验要求：\n3年以上互联网产品营销、或品牌相关工作经验，有从0到1产品推广经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100006800010","sourceKey":"quark_social","company":"夸克","title":"千问事业部-产品市场营销专家-杭州","city":"杭州","category":"市场-产品市场营销","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100006800010&track_id=SSP1791223758588QMIQWvzEZW9174","duty":"1、对智能硬件，AI硬件等新品类产品发展态势敏感，能基于业务洞察构建产品营销体系，熟悉GTM为牵引的工作流，可以通过营销方案落地，驱动产品、销售、运营、算法&技术等多部门协同。\n2、承接品牌策略、目标顾客洞察、产品技术和功能，制定产品营销的目标及路径策略，输出产品营销创意核心策略，有效提炼产品卖点，制定整个生命周期在线上、线下、通路营销各维度的营销方案与项目管理，确保按计划执行落地，不断提升产品的认知度、考虑度与转化率；\n3、从产品立项阶段开始参与新品从上市到发布到热销到退市再迭代的生命周期全流程，通过产品发布策划、产品传播策划等关键策略，开展产品声量舆情运营、销售渠道营销支持，联动产品研发、运营及线上、线下零售&渠道销售，推动实现用户增长的核心目标，对产品的成功上市负责。主导产品营销的广告前测、Campaign策划与效果评估等项目，定期进行复盘分析；\n4、独立协调和推动公司内部资源，多快","requirements":"1、5年及以上消费品（或消费电子领域）市场相关从业经验，对硬件产品行业有深度的理解；\n2、对互联网行业及市场操作方式有所了解，对品牌传播、企业级产品、大众传播具备独到见解；\n3、有负责重点产品上市操盘经验优先；\n4、具备在规划化组织带领或推进项目的执行经验，有团队管理经验优先；\n5、具备较强的学习能力，可以快速了解新行业及新领域，具备好奇心及学习精神，能在高压下保持自我驱动、自我学习、自我管理。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100006820007","sourceKey":"quark_social","company":"夸克","title":"千问事业部-高级硬件系统架构专家-杭州/深圳/上海","city":"深圳/杭州/上海","category":"技术类-开发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100006820007&track_id=SSP1791223760627VvDmnirWpJ3962","duty":"1. 对各产品系统方案竞争力负责，主导产品线软硬结合系统方案设计，并负责牵头相关问题攻关解决，确保各子品类产品系统方持续保持竞争力领先；\n2. 根据未来产品矩阵规划，主导芯片平台路标制定、新功能模块布局及落地把关；\n3, 从用户需求和行业动态中挖掘硬件功能创新机会点，推动并主导内部提前做好相关技术布局，形成产品卖点及技术壁垒；\n4. 与整机架构共同负责竟品分析，并搭建行业技术洞察与引入评估机制；\n5. 负责承接产品线新软硬结合相关功能，并串连相关研发领域，主导跨多技术领域预研, 确保最终方案可落地性急领先性。","requirements":"1. 本科及以上学历，电子、通讯、自动化相关专业；\n2. 熟悉移动、穿戴、智能硬件主流SOC平台特性和路标演进; 精通存储、电源与功耗、传感器、显示、触控、音频、接口协议、EMC与ESD、互连等领域技术；\n3. 10年以上硬件领域开发经验，主导过8款以上手机、平板、AI眼镜等消费电子或智能硬件产品的硬件系统架构设计及开发落地；\n4. 具备较强的前瞻创新思维与成功案例、能深入研究行业前沿技术，并结合业务与产品需求，透过技术引进或技术预研，确保产品竞争力；\n5. 具备产品线硬件系统架构负责人经验，有良好的跨领域协同能力与逻辑思维，有丰富的0到1主导新平台、新器件、新技术落地成功经验，并能沉淀与复制，形成技术壁垒。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100006820008","sourceKey":"quark_social","company":"夸克","title":"千问事业部-业务内控专家-广州/北京/杭州","city":"北京/杭州/广州","category":"风险管理-内控内审","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100006820008&track_id=SSP1791223757880YaurfOPiqh8056","duty":"1、协同业务及财法团队，平衡风险和效率，制定和更新恰当的流程、制度、权限等，进行合理风险管控，完成管理落地并持续监控，确保公司各项业务符合法律法规、行业规范和公司战略目标。\n2、对业务及财务数据进行分析，快速、准确识别业务当前风险及现存问题，并提出有效的、可落地的数字化解决方案，跟进解决方案落地。\n3、依托业务流程、数据链路及核心业务系统，构建多维风险监控指标体系，形成系统性数据监测方案，实现业务全流程的风险识别与精准评估。\n4、参与业务重大/创新项目，在事前、事中提供有针对的风险研判和应对建议，对业务方的策略进行风险洞察和判断，并给出风险评估和应对方案。\n5、根据业务特点制定专项计划，通过项目检视，深入识别在业务设计及执行层面的风险，并对风险程度进行评估，提出有效的改进建议并协同各方进行改善，把风险控制在可接受范围内。","requirements":"1、6年以上行业内部控制或风险管理相关工作经验，有四大及大型互联网公司从业背景优先。\n2、具备对业务的快速理解和敏锐的风险洞察能力，掌握风险识别、分析、评估以及内部控制方面的方法论体系及具体操作技能。\n3、善于跨部门合作，具有较强的沟通协调、组织管理、团队合作和领导能力，能够有效推动工作的落地执行。\n4、具有优异的独立分析及解决问题的能力、较强的逻辑思维，能够根据业务发展需要不断完善和优化内部控制体系。\n5、熟练掌握SQL或Python，具备扎实的数据处理、分析与数字化运营能力，拥有CPA、CIA、CISA等专业资质者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100006820010","sourceKey":"quark_social","company":"夸克","title":"千问事业部-交付管理专家-深圳/上海/杭州","city":"深圳/杭州/上海","category":"供应链-生产供应链管理","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100006820010&track_id=SSP1791223758588RaWhUxGJbC3145","duty":"1、督促计划组及时更新FCST,落实代工厂备货状况并根据需求下达采购订单；\n2、协助并督促代工厂及时根据生产和试产的需求,按时齐套进料计划；\n3、定期要求与供应商沟通，及时了解他们的生产计划、备货、货源及公司状况；\n4、不定期的按公司项目的状况及需求量,对供应商做到风险排查；\n5、物料和整机交付；\n6、定期组织供应商绩效考核和QBR会议。","requirements":"1、本科及以上学历，电子，机电，机械及管理类相关专业背景；\n2、5年以上行业采购与交付管理工作经验；\n3、有责任心，具备较强的抗压能力和团队合作精神；\n4、有完成项目并取得财务成果经验，有建立团队或带团队进行流程或者项目改善的经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100007300005","sourceKey":"quark_social","company":"夸克","title":"千问事业部-AI产品运营专家（用户活跃方向）-杭州/北京","city":"北京/杭州","category":"运营-产品运营","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100007300005&track_id=SSP1791223754151hLafBatmEu5855","duty":"1. 负责端内用户全生命周期的活跃运营，从拉新、促活、留存到召回，设计并落地精细化运营策略，系统性提升用户粘性与长期价值；\n2. 围绕 Chat 产品核心场景，结合大模型能力迭代，持续优化交互路径与内容推荐机制，驱动用户行为规模（如对话频次、会话深度、功能使用率）稳步增长；\n3. 协同算法、产品、数据团队，推动策略在 AI 对话场景中的落地应用，提升用户发现效率与使用黏性；\n4. 建立用户活跃度监测体系与指标看板，定期输出洞察报告，为产品决策提供数据支撑。","requirements":"1. 本科及以上学历，计算机、统计学、心理学、经济学或相关理科/数据运营背景优先；\n2. 3年以上互联网产品/运营经验，具备大模型/AI产品实战经验者优先；\n3. 有搜索/推荐策略运营经验，熟悉用户兴趣建模、内容分发机制、CTR/CVR优化者优先考虑；\n4. 熟练使用 SQL / Python / Excel 等数据分析工具，能独立完成数据提取、清洗、分析及可视化，具备用数据驱动决策的能力；\n5. 对 AI 产品有热情，关注前沿技术趋势，具备良好的用户同理心与商业敏感度，善于在理性分析与感性体验间找到平衡点。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100008180002","sourceKey":"quark_social","company":"夸克","title":"千问事业部-千问/夸克-语音AI产品经理-杭州/北京","city":"北京/杭州","category":"产品类-用户型","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100008180002&track_id=SSP1791223758936secKkwUhpE9120","duty":"● 语音核心体验提升\n负责语音基础能力在产品内的体验升级（语音输入、播报、搜索、实时通话等），定制优化策略，推动语音功能使用率、留存、转化的数据指标提升，推动产品内用户语音心智建立\n\n● 语音交互产品功能优化\n负责语音交互相关的产品功能设计和落地，深入挖掘用户需求，设计产品方案和优化策略，驱动产品迭代；能独立提出需求并推动产品和研发落地，确保体验和指标提升。\n\n● 推动语音模型效果提升\n负责 ASR、TTS、E2E、多模态模型的用户侧效果验证机制搭建，与算法团队合作，结合产品需求，拆解合理的算法评价指标，搭建评测体系，推动算法快速迭代","requirements":"基本要求：\n1、本科及以上学历，专业不限（计算机、电子、心理学、认知科学、人机交互优先）；\n2、3-7年AI产品经验（有独立项目落地能力）\n3、逻辑清晰、表达能力强，具备良好的跨团队沟通能力与推动力，可与产品、研发、算法高效协作，有复杂项目协同和推进落地力能力；\n4、对 AI、语音交互、多模态交互、智能产品有热情；\n\n加分项：\n1、有语音相关产品/大模型方向实习经验；\n2、有 ASR、TTS 、LLM或多模态端到端模型产品经验 ；\n3、有亮点产品或项目落地经验；\n4、对声音敏感，有审美能力","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100008180008","sourceKey":"quark_social","company":"夸克","title":"千问事业部-用增中台产品专家-（千问/夸克）","city":"广州","category":"产品类-平台型","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100008180008&track_id=SSP1791223755861olTHdRAdgN4101","duty":"1.对互联网拉新产品全渠道归因策略有相关积累经验，根据总体目标主导实施归因策略优化实验及落地。\n2.熟悉媒体投放实时质量识别和流量识别策略，主导落地全局最优回调策略实验和落地，对规模，成本，质量目标负责。\n3.负责一个或多个中台系统建设，有相关经验，如信息流投放运营系统，aigc批量化素材系统\n4.有比较强的数据分析能力，有增长投放全链路视角，善于发现和定位投放过程中的问题，并推动解决相关问题","requirements":"1.本科以上学历\n2.3年以上互联网大厂用户增长中台相关工作经验，熟悉归因策略，投放回调策略，用户承接策略，熟悉全渠道增长策略\n3.主持主导过自动投放系统，aigc物料系统等增长中台系统建设\n4.熟悉sql命令，有较强的数据分析能力，有研发或工科背景优先，有较强沟通协调能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100008380011","sourceKey":"quark_social","company":"夸克","title":"千问事业部-用户增长BP/PMO（PC&web）-广州/北京","city":"北京/广州","category":"运营-产品运营","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100008380011&track_id=SSP1791223755861vDRoCIKYtw9611","duty":"1、 负责千问PC客户端和千问网页版的用户增长工作，为用户规模目标负责\n2、 设计并各渠道的拉新促活策略，包括但不限于SEM、SEO、GEO、达人营销、信息流投放、厂商合作、二/三方合作等，明确商业模式，制定投放预算，并评估投放效果\n3、 深入洞察AI产品的行业趋势、业务痛点及用户需求，和产研团队沟通协作，挖掘端内和端外场景的新用户增长机会点\n4、 以数据驱动用户增长产品体验和增长策略的持续改进，推动产品侧的迭代升级及转化率提升，落地新的增长玩法/场景/合作模式。","requirements":"1、本科以上学历，3年以上C端产品或运营经验，有PC端产品增长或商业化项目经验优化\n2、了解目前AI领域主流的PC端产品推广方式，包括但不限于SEM、SEO、GEO、达人营销、信息流投放、厂商合作、二/三方合作等，对其中某一种或某几种增长渠道有深入了解\n3、 逻辑清晰，有敏锐的业务意识，较强的自驱力及韧性，以目标结果为导向，执行力强，有团队协作意识，能够积极推动业务合作落地，有业务协作、资源拓展经验者优先；\n4、 较强的策略能力和数据敏感度，具有良好的沟通和跨部门共建能力，富有激情、创造性、抗压能力和责任心。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100008400008","sourceKey":"quark_social","company":"夸克","title":"千问事业部-夸克-推荐算法专家-资源推荐-北京","city":"北京","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100008400008&track_id=SSP1791223756877VWhhfnuynk1788","duty":"1. 负责通用搜索场景下资源（小说、视频、软件、游戏、漫画等）推荐相关的召回、排序、策略等算法设计与技术规划；\n2. 参与制定推荐算法策略和流程，使用机器学习和深度学习技术维护和更新模型，确保推荐算法的质量和效率；\n3. 与产品经理、数据科学家、产品运营专家等合作，确保推荐系统的设计和实现符合需求。","requirements":"1、扎实的算法和数据结构基础，优秀的业务理解能力和编码能力，有推荐算法1年以上研发经验；\n2、机器学习基础理论扎实，熟悉常用的推荐算法模型（如SWING、DeepFM、DIN、端到端推荐），对模型调优有一定实践经验；\n3、对推荐系统召回/排序/多样性/冷启动中一个或多个方向有过深入的实践，熟悉业界经典的模型和方法；\n4、熟悉至少一门编程语言（java/python），熟悉至少一种神经网络框架（Tensorflow、Pytorch），熟悉Linux开发环境；\n5、善于沟通，乐观自信，良好的团队合作精神；对新技术充满好奇，能够持续学习，乐于实践，无惧试错。\n\n加分项 ：\n1、有个性化推荐、广告、搜索等相关领域的项目经验；\n2、在KDD、NeurIPS、WWW、SIGIR、WSDM、CIKM、ICLR、ICML、IJCAI、AAAI、RecSys等会议发表过论文优先；\n3、有高关注度的机器学习相","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100008420012","sourceKey":"quark_social","company":"夸克","title":"千问事业部-用户增长-SEM渠道运营","city":"北京","category":"运营-用户运营","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100008420012&track_id=SSP1791223760285rvUyRfKUHB8885","duty":"负责夸克、千问业务在搜索渠道的整体资源布局和投放运营，整合、协同代理商和媒体资源，将业务多元化卖点转化为高效获客素材，主导投放策略系统化升级，推动跨部门（如产研、数据、算力团队）配合，实现SEM投放能力持续优化，为业务降本增效提供坚实的系统能力支撑，高效达成业务增长与留存目标。","requirements":"1、本科及以上学历， 3年以上SEM投放应用推广类产品的实操经验，有商务、市场营销、数据分析或相关领域专业背景优先。\n2、对搜索媒体、行业情况、搜索逻辑具备深刻洞察，熟练掌握SEM投放体系与主流平台操作（如百度、Bing、360等），具备信息收集、数据分析、效果评估能力；\n3、具备洞察业务需求并转化为搜索渠道营销创意的能力，善于用创新思维提升获客效率；\n4、具备高效的整合资源与项目管理能力，能够统筹代理商及内部跨团队协同，能够协调多方资源，推动投放项目高质量落地；\n5、结果导向与系统化思维，能在复杂环境下持续优化投放效果与成本结构。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100008800001","sourceKey":"quark_social","company":"夸克","title":"千问事业部-内容业务AI Agent运营专家-广州","city":"广州","category":"运营类-内容运营","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100008800001&track_id=SSP1791223759289KFxjEhKFEu8496","duty":"1、负责UC浏览器内容业务的AI Agent运营工作，包括Agent技能的策略制定、流程编排、效果追踪与持续优化，推动内容供给、生产和流转效率提升。\n2、深入理解内容业务场景（如内容入库、安全审核、版权评估、垂类分发等），将业务需求转化为Agent可执行的任务流程，搭建并维护Agent的技能体系、知识库和运营SOP。\n3、建立Agent运营效果的评估指标体系，通过数据分析定位瓶颈，结合Harness工程方法（Prompt优化、Case积累、评测迭代）持续提升Agent的任务完成质量。\n4、与算法、技术、业务方紧密协作，负责Agent上线后的日常运维、异常处理、版本迭代跟进，确保Agent稳定服务于业务目标。","requirements":"1、本科及以上学历，3年以上互联网内容运营或策略运营经验，有AI工具落地运营、自动化流程运营经验者优先。\n2、具备扎实的内容理解能力，熟悉内容平台的供给链路，能准确识别业务痛点并抽象为可自动化的运营流程。\n3、对AI Agent的基本架构（如多步推理、工具调用、记忆机制）有了解或有强烈的学习意愿，能理解Agent能力边界并合理设计运营策略；有Agent/RPA/自动化流程实操经验者优先。\n4、优秀的跨团队协作和项目推进能力，能与算法工程师高效沟通技术方案，推动多方对齐落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100009180003","sourceKey":"quark_social","company":"夸克","title":"千问事业部-MOS 实验室-AI搜索算法专家-杭州/北京","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100009180003&track_id=SSP1791223753808fqsBaVJrmR2259","duty":"关于我们：\nMOS 实验室隶属于阿里 ATH 千问事业群。我们致力于在大模型时代打造具有全球影响力的 AI 原生产品，推动 AI 从“被动对话”向“主动服务与复杂执行”的范式跃迁。\n实验室核心业务涵盖 AI 搜索、生成式推荐、主动服务及任务助理 Agent 等前沿领域。依托千问大模型底座，我们深度探索 RAG、Agentic RL、多 Agent 协作及全链路工程自动化技术，旨在构建能够深度理解用户、自主规划路径并闭环交付任务的“最强 AI 助手”。\n岗位职责：深耕全链路 AI 搜索与 Agent 技术\n1. AI 搜索核心技术研发： 负责 AI 搜索场景下的核心算法研发，包括但不限于索引构建与收录、向量召回、 LLM 相关性模型以及生成式检索与排序的构建与优化。\n2. 垂直领域 RAG 落地： 利用大模型技术（LLM）实现行业深度搜索，攻克垂直领域下的语义对齐、知识抽取及结构化数据检索等","requirements":"我们正在寻找两类核心人才，只要你符合其中之一，欢迎与我们共同定义未来：\n方向一：搜索资深专家（向 AI 场景转型）\n● 具备丰富的搜索系统研发经验， 熟悉搜索基础算法与工程技术，对搜索业务有深刻理解。\n● 希望将深厚的搜索积淀与大模型技术结合，实现技术的代际跨越。\n方向二：AI 应用/大模型新锐（深耕搜索赛道）\n● 在 LLM、RAG、或智能 Agent 领域有扎实的实战经验。\n● 希望在搜索这一垂直赛道深入研究，通过解决复杂的检索与生成问题，提升核心算法竞争力。\n基础能力：\n● 计算机、数学或相关专业本科及以上学历，具备优秀的编程能力（Python/Java/C++ 至少一种）。\n● 熟悉常见的深度学习框架（PyTorch/TensorFlow）及大模型落地工具。\n● 对技术充满热情，具备极强的逻辑分析能力和解决未知问题的自驱动力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100009540002","sourceKey":"quark_social","company":"夸克","title":"千问事业部-高级前端开发工程师-广州","city":"广州","category":"技术类-前端","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100009540002&track_id=SSP1791223756549oHRjqOxiSx1885","duty":"1、负责配合大数据、云原生调度、训推引擎、搜推引擎等团队一起打造卓越的AI基础设施中台，助力AI业务高速迭代；\n2、负责前端智能研发方向的关键技术的调研及应用，不断提升团队整体的开发效率。","requirements":"1、本科及以上学历，计算机等相关专业。2年以上前端工作经验，精通HTML5、CSS3、JavaScript 、React、TypeScript等技术及原理，熟悉网络协议（HTTP/SSL）；\n2、具备扎实的编程基本功和大型中后台项目（React）的开发经验，熟悉前端工程与模块化开发，并有实践经验（如 Umi / Webpack / vite / pnpm 等），具备独立完成复杂前端页面布局、交互设计、组件开发与性能优化的能力，能够识别并运用各种技术提升系统整体性能与用户体验； \n3、熟悉前后端协同流程，对如何进行前后端的高效解耦与协同开发有相关经验；熟悉一门非前端的语言（如 node / Python / Rust / Go 等），并有实践经验； \n4、具备良好沟通能力和团队协作能力，能清晰、准确表达技术或业务观点，能高效地进行跨团队协作； \n5、具备较强的自驱力，对新技术有较强的学习能力","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100009980050","sourceKey":"quark_social","company":"夸克","title":"千问事业部-软件项目管理专家-杭州/上海","city":"杭州/上海","category":"技术类-综合","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100009980050&track_id=SSP1791223756877BQMKPMfZAw1067","duty":"1. 负责智能硬件系统软件开发的整个过程，包括从项目的启动阶段到量产阶段；\n2. 带领软件团队一起按时完成产品从定义到量产的端到端的工作，使产品达到质量要求和体验要求；\n3. 负责项目资源的协调与组织，确保项目团队各干系人协同工作，达到项目目标；负责项目节奏及计划制定，确保项目进度以及项目质量；进行项目风险控制、及时发现跟踪解决影响项目进度相关问题；\n4. 不断优化软件开发等相关流程。","requirements":"1. 大学本科或以上学历，计算机、通信或相关专业；\n2. 5年以上智能硬件或手机等相关行业软件项目管理经验，或技术leader经验，带过成功面市的智能硬件项目，有通用项目管理能力及证书优先；\n3. 有研发背景，尤其是底层或系统研发背景，了解智能硬件或手机行业的发展状况；\n4. 具有丰富的与人沟通、交流和组织能力，出色的团队合作精神，工作积极主动，抗压能力强，善于发现并跟踪解决项目过程中的问题，有效控制项目风险；\n5. 较强的问题分析能力、文档撰写能力及各类报告处理能力，具有良好的执行力和责任心，能推动项目团队朝目标前进。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100010020058","sourceKey":"quark_social","company":"夸克","title":"千问事业部-技术解决方案专家-杭州","city":"杭州","category":"技术类-综合","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100010020058&track_id=SSP1791223759948lGAUxNKPoH1585","duty":"1. 主导重点行业PoC（概念验证）方案的端到端建设，覆盖需求调研、方案设计、技术验证、效果评估及交付复盘全过程；\n2. 与客户深度共建，结合公司产品能力与前沿技术（如人工智能、大模型等），打造可落地、可复制的行业标杆解决方案；\n3. 高效协同内部产品、算法、研发及交付团队，确保方案技术可行性、先进性与实施效率；\n4. 沉淀行业方法论与最佳实践，推动成功方案在垂直行业内的规模化复制与推广；\n5. 持续跟踪行业技术趋势与客户需求变化，为产品演进和解决方案创新提供一线输入。","requirements":"1. 本科及以上学历，5年以上技术解决方案相关经验者优先；\n2. 对所聚焦的行业有较深入的理解，熟悉行业典型业务流程、关键挑战及未来趋势；\n3. 具备出色的沟通表达与需求理解能力，能够高效对接客户高层及技术团队，准确提炼需求并转化为清晰的技术方案；\n4. 有较强的项目推动能力和跨团队协作意识，能主导PoC项目和客户项目从0到1的闭环落地；\n5. 对智能硬件和AI技术有一定的了解，能够评估其在具体行业场景中的适用性与落地路径，具备将技术能力转化为业务价值的能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"quark_social:100010040044","sourceKey":"quark_social","company":"夸克","title":"千问事业部-产品线计划管理专家-杭州/上海","city":"杭州/上海","category":"项目管理-业务项目管理","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://talent.quark.cn/off-campus/position-detail?positionId=100010040044&track_id=SSP1791223758588HMMIQKtCbp3717","duty":"1、对接GTM和销售要货需求，结合PSI数据，组织S&OP的需求计划编制、决策和管理，牵引供应链PC和MC计划基于整机成品需求计划向下分解为物料齐套计划以及整机生产/出货计划；\n2、牵引端到端领域进行整机和物料责任量的数据对齐，全面整合渠道库存、整机PO、物料责任量的数据并及时预警风险；推动GTM和销售渠道达成整机提货率和要货计划准确率；\n3、基于S&OP需求的交付节奏，制定产能规划和战略物料规划需求；对销售侧的提货达成率和PSI数据进行整合管理，及时调控S&OP并及时上报库存风险驱动决策调控库存消耗的操盘策略；\n4、发布S&OP计划及整机交付和ITO分析报告，推动端到端领域优化改进。","requirements":"1、本科及以上学历，8年及以上消费电子产品产品线整机端到端计划管理工作经验；\n2、熟悉销售和渠道销货逻辑以及用户订单、仓储物流发货逻辑；\n3、熟悉S&OP管理机制，熟悉从整机需求到物料管理，以及ERP/MPS/MRP系统逻辑；\n4、具备较强的沟通能力、执行力和抗压能力。","description":"","jdComplete":true,"sourceStatus":null}];
